export type AzureRbacCategory =
  | 'General' | 'Security' | 'Compute' | 'Storage' | 'Networking'
  | 'Database' | 'Identity' | 'Monitoring' | 'Containers'
  | 'AppService' | 'Integration' | 'Management' | 'AI'

export type AzureRbacTier =
  | 'FullControl' | 'AccessManagement' | 'Contributor'
  | 'DataPlane' | 'Reader' | 'Specialized'

export type AzurePermType = 'Actions' | 'NotActions' | 'DataActions' | 'NotDataActions'

export interface AzureRbacPermission { action: string; type: AzurePermType }

export interface AzureRbacRole {
  name: string; slug: string; id: string; description: string
  category: AzureRbacCategory; tier: AzureRbacTier
  isPrivileged: boolean; permissionCount: number; assignableScopes: string[]
}

